#!/usr/bin/env python3
"""Apply v9 search/compat/postcondition hardening to verified v8 source."""
from pathlib import Path


def patch(path: str, old: str, new: str, count: int = 1) -> None:
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    actual = text.count(old)
    if actual != count:
        raise SystemExit(f"{path}: expected {count}, found {actual}: {old[:100]!r}")
    p.write_text(text.replace(old, new, count), encoding="utf-8")


def replace_between(path: str, start: str, end: str, new_block: str) -> None:
    p = Path(path)
    text = p.read_text(encoding="utf-8")
    si = text.find(start)
    ei = text.find(end, si + len(start))
    if si < 0 or ei < 0:
        raise SystemExit(f"{path}: missing block anchors {start!r} -> {end!r}")
    p.write_text(text[:si] + new_block.rstrip() + "\n\n" + text[ei:], encoding="utf-8")


